// Presentation recipes translated from scripts/living_effects.gd, no model RNG.
#include "tactical_living_internal.hpp"
#include <algorithm>
#include <cmath>
#include <numbers>
#include <SDL.h>
namespace transartica::panels {
using namespace visual;namespace {constexpr double pi=std::numbers::pi,tau=2*pi;bool is(const std::string&n,std::initializer_list<const char*>values){for(auto*v:values)if(n==v)return true;return false;}}
LivingEffects::LivingEffects(std::filesystem::path path):impl_(std::make_unique<Impl>(std::move(path))){}
LivingEffects::~LivingEffects()=default;
void LivingEffects::ember(Point point,Point velocity,int lifetime,Point extent,SDL_Color color,double scale) {
    impl_->launch("ember",point,velocity,lifetime,extent,
        {color.r/255.,color.g/255.,color.b/255.,color.a/255.},scale);
}
void LivingEffects::Impl::launch(std::string kind,Point point,Point velocity,int life,Point extent,Color color,double scale,double angle,double floor){if(particles.size()>=2048)particles.erase(particles.begin());particles.push_back({std::move(kind),point,velocity,extent,point,color,0,life,scale,angle,floor,false,false});}
void LivingEffects::Impl::burst(const Emitter&e,int amount){for(int i=0;i<amount;++i){const bool snow=i%3==0||e.kind=="snow";const double angle=rnd(pi,tau),speed=rnd(20,70);const Point velocity=from_angle(angle)*(speed*e.scale);const double extent=rnd(.25,.75)*e.scale;launch(snow?"snow":"spark",e.point,velocity,snow?75:45,{extent,extent},color(snow?0xdbe5ea:0xffd27a),e.scale);}}
void LivingEffects::Impl::plume(const Emitter&e){if(e.explosive||e.gun||e.kind=="impact")return;const bool rocket=is(e.kind,{"rocket","rocket-exhaust"});if(rocket||is(e.kind,{"smoke","steam","dust"})){const std::string name=is(e.kind,{"steam","dust"})?e.kind:"smoke";const double dx=rnd(-4,4);const double vx=rnd(-6,6),vy=rnd(-16,-8);launch(name,e.point+Point{dx,-2}*e.scale,Point{vx,vy}*e.scale,100,Point{10,10}*e.scale,{1,1,1,1},e.scale);}if(rocket)launch("rocket",e.point,e.direction*(20*e.scale),12,Point{9,22}*e.scale,{1,1,1,1},e.scale,std::atan2(e.direction.y,e.direction.x)-pi/2);}
void LivingEffects::add(std::string kind,Point point,Point direction,double scale){if(!std::isfinite(scale)||scale<=0)return;auto&i=*impl_;++i.serial;i.random.seed(art::visual_seed(kind,point,i.serial));if(i.emitters.size()>=128)i.emitters.erase(i.emitters.begin());const bool explosive=is(kind,{"destroy","dynamite","explosion","rocket-impact"}),gun=is(kind,{"cannon","machinegun","muzzle"});int duration=explosive?150:kind=="impact"?50:30;if(is(kind,{"steam","smoke","dust"}))duration=75;const Emitter emitter{kind,point,norm(direction),0,duration,explosive,gun,scale};i.emitters.push_back(emitter);i.add_volume(kind,point,norm(direction),scale);if(explosive||is(kind,{"impact","sparks","shot","melee","snow"}))i.burst(emitter,explosive?48:16);
    if(explosive||kind=="impact"){const double size=explosive?1:.55;i.launch("flash",point,{},3,Point{16,12}*(size*scale),{1,1,1,1},scale,i.rnd(0,tau));i.particles.back().radial=true;i.launch("glow",point,{},explosive?12:7,Point{30,30}*(size*scale),color(0xffb45a),scale);i.launch("ring",point+Point{0,4}*scale,{},14,Point{30,9}*(size*scale),color(0xfff1c2),scale);for(int n=0;n<(explosive?8:3);++n){const double angle=i.rnd(pi*1.1,pi*1.9),speed=i.rnd(40,95);const Point velocity=from_angle(angle)*(speed*scale);const int life=i.randi(45,80);i.launch("ember",point,velocity,life,Point{.75,.75}*scale,color(0xffb347),scale);i.particles.back().trail=true;}}
    if(kind=="cannon"){const Point aim=norm(direction);i.launch("flash",point,{},4,Point{9,7}*scale,{1,1,1,1},scale,std::atan2(aim.y,aim.x));i.launch("glow",point,{},6,Point{14,14}*scale,color(0xffb45a),scale);i.launch("ring",point,{},10,Point{16,6}*scale,color(0xfff1c2),scale);i.launch("projectile",point,aim*(600*scale),12,Point{10,.75}*scale,color(0xfff1c2),scale);for(int puff=0;puff<6;++puff){const Point side{puff%2==0?-1.:1.,0};const double across=i.rnd(20,45),forward=i.rnd(5,25);const int life=i.randi(60,95);i.launch("steam",point+aim*2,(side*across+aim*forward+Point{0,-6})*scale,life,Point{5,5}*scale,{.84,.85,.88,.6},scale);}}
    const double jolt=kind=="destroy"||kind=="rocket-impact"?1.5:kind=="dynamite"||kind=="explosion"?1.25:kind=="cannon"?.6:kind=="impact"?.9:0;i.shake=std::min(1.5,i.shake+jolt);i.plume(emitter);
}
void LivingEffects::fire_round(Point point,Point direction,int number,double heat,double floor,double reach,bool armour,Point breech){auto&i=*impl_;i.random.seed(art::visual_seed("round",point,++i.serial));const double turn=i.rnd(-.03,.03);const Point aim=rotated(norm(direction),turn);const double ex=i.rnd(5,8),ey=i.rnd(3,4.5),angle=std::atan2(aim.y,aim.x)+i.rnd(-.4,.4);i.launch("flash",point,{},2,{ex,ey},{1,1,1,1},1,angle);i.particles.back().radial=direction.y>0;const double glow=i.rnd(7,9);i.launch("glow",point,{},3,{glow,glow},color(0xffb45a));const bool tracer=number%3==0;const int life=std::max(1,int(std::ceil(reach/900/.02)));i.launch("projectile",point,aim*900,life,{tracer?14.:9.,tracer?.75:.5},tracer?color(0xfff1c2):Color{1,.85,.6,.45});i.pending.push_back({i.clock+life,point+aim*reach,armour?"sparks":"snow"});const double vx=i.rnd(14,32),vy=i.rnd(-38,-22);const Point origin=std::isfinite(breech.x)&&std::isfinite(breech.y)?breech:point+Point{1.5,-1};const int brasslife=i.randi(110,160);const double brassangle=i.rnd(0,tau),brassfloor=floor+i.rnd(-.5,.5);i.launch("casing",origin,{vx,vy},brasslife,{1.75,.75},color(0xd9a648),1,brassangle,brassfloor);if(number%3==1||heat>.6){const double sx=i.rnd(-4,4),sy=-i.rnd(5,10);const int smokelife=i.randi(35,60);i.launch("steam",point,{sx,sy},smokelife,Point{1,1}*(2.5+heat*2.5),{.86,.87,.9,.4});}}
void LivingEffects::fragments(Point point,const std::vector<SDL_Color>&colors){auto&i=*impl_;for(const auto&c:colors){const double vx=i.rnd(-45,45),vy=i.rnd(-65,-15),ex=i.rnd(.5,1.25),ey=i.rnd(.25,.75);i.launch("debris",point,{vx,vy},75,{ex,ey},{c.r/255.,c.g/255.,c.b/255.,c.a/255.});}}
void LivingEffects::Impl::ricochet(Point point,const std::string&material){random.seed(art::visual_seed("ricochet",point,clock));if(material=="sparks"){for(int n=0;n<5;++n){const double angle=rnd(pi,tau),speed=rnd(25,60);const int life=randi(8,16);launch("spark",point,from_angle(angle)*speed,life,{.5,.5},color(0xffd27a));}}else{for(int n=0;n<4;++n){const double vx=rnd(-14,14),vy=rnd(-30,-12);const int life=randi(20,35);launch("snow",point,{vx,vy},life,{.5,.5},color(0xe8f0f5));}launch("dust",point,{0,-4},30,{4,4},{1,1,1,.5});}}
void LivingEffects::Impl::step(){++clock;shake*=.8;for(const auto&hit:pending)if(hit.clock<=clock)ricochet(hit.point,hit.material);std::erase_if(pending,[&](const Pending&p){return p.clock<=clock;});std::vector<Point>trails;for(auto&p:particles){++p.age;if(p.trail&&p.age<p.life*.8)trails.push_back(p.point+Point{std::sin(p.age*2.3),std::cos(p.age*1.7)}*.5);if(is(p.kind,{"snow","spark","debris","ember","casing"})){p.velocity.y+=100*(p.kind=="casing"?2.5:1)*.02*p.scale;p.angle+=p.velocity.x*.02*(p.kind=="casing"?1.4:.1);}p.point=p.point+p.velocity*.02;if(std::isfinite(p.floor)&&p.point.y>p.floor&&p.velocity.y>0){p.point.y=p.floor;p.velocity={p.velocity.x*.55,-p.velocity.y*.35};if(std::abs(p.velocity.y)<6){p.velocity={};p.angle=std::round(p.angle/pi)*pi;}}}std::erase_if(particles,[](const Particle&p){return p.age>=p.life;});for(Point p:trails)launch("soot",p,{0,-4},36,{.5,.5},{.2,.2,.22,.75});step_volume();for(auto&e:emitters){++e.age;if(e.age%4==0&&e.age<e.duration/2)plume(e);}std::erase_if(emitters,[](const Emitter&e){return e.age>=e.duration;});}
void LivingEffects::advance(double seconds,const std::function<void()>& before_step){auto&i=*impl_;if(!std::isfinite(seconds)||seconds<=0)return;i.remainder+=seconds;while(i.remainder>=.02||std::abs(i.remainder-.02)<.00001){i.remainder=std::max(0.,i.remainder-.02);if(before_step)before_step();i.step();}}
void LivingEffects::clear(){const auto path=impl_->assets;impl_=std::make_unique<Impl>(path);}
Point LivingEffects::shake_offset()const{const auto&i=*impl_;return i.shake<.05?Point{}:snap(Point{std::sin(i.clock*2.7),std::cos(i.clock*3.3)}*i.shake);}
std::size_t LivingEffects::particle_count()const{return impl_->particles.size();}
void LivingEffects::draw(Canvas&c,Point offset){const auto previous_projection=visual::world_projection;struct ProjectionRestore{std::optional<visual::Projection>previous;~ProjectionRestore(){visual::world_projection=previous;}}projection_restore{previous_projection};if(!previous_projection)visual::world_projection=visual::projection(c);SDL_BlendMode previous;SDL_GetRenderDrawBlendMode(c.renderer(),&previous);impl_->load(c);impl_->draw_volume(c,offset);impl_->draw_particles(c,offset,false);impl_->draw_particles(c,offset,true);SDL_SetRenderDrawBlendMode(c.renderer(),previous);}
void LivingEffects::draw_world(Canvas&c,Point origin,double zoom){if(!std::isfinite(zoom)||zoom<=0)return;const auto previous=visual::world_projection;struct Restore{std::optional<visual::Projection>previous;~Restore(){visual::world_projection=previous;}}restore{previous};visual::world_projection=visual::Projection{float(origin.x),float(origin.y),float(zoom)};draw(c);}
void LivingEffects::draw_light(Canvas&c,Point offset){SDL_BlendMode previous;SDL_GetRenderDrawBlendMode(c.renderer(),&previous);impl_->draw_particles(c,offset,true);SDL_SetRenderDrawBlendMode(c.renderer(),previous);}
void LivingEffects::draw_atlas(Canvas&c,const std::string&name,Point p,Point extent,SDL_Color color,double angle){SDL_BlendMode previous;SDL_GetRenderDrawBlendMode(c.renderer(),&previous);impl_->load(c);impl_->atlas(c,name,p,extent,{color.r/255.,color.g/255.,color.b/255.,color.a/255.},angle);SDL_SetRenderDrawBlendMode(c.renderer(),previous);}
}
